import numpy as np
from numpy.linalg import lstsq
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
def run(gx,name):
    cols=[];labs=[]
    for vn,vf in [('1/v',1/v),('v',v),('1',np.ones_like(v)),('v2',v*v)]:
        for gn,g in gx:
            cols.append(vf*g); labs.append(vn+'*'+gn)
    A=np.array(cols).T
    c,_,_,_=lstsq(A,a,rcond=None); r=np.sum((a-A@c)**2)/np.sum((a-a.mean())**2)
    print(name,'nmse',r)
    return r,c,labs
g1=[('1',np.ones_like(x)),('x',x),('x2',x**2),('sinx',np.sin(x)),('cosx',np.cos(x))]
r,c,l=run(g1,'trig')
for n,cc in zip(l,c):
    if abs(cc)>0.02: print(n,round(cc,4))
g2=[('1',np.ones_like(x)),('x',x),('x2',x**2),('x3',x**3)]
r2_,c2,l2=run(g2,'poly3')
for n,cc in zip(l2,c2):
    if abs(cc)>0.02: print(n,round(cc,4))
